import { fireEvent, render, screen, waitFor } from "@testing-library/react"
import { beforeEach, expect, test, vi } from "vitest"
import { App } from "./App"

beforeEach(() => {
  localStorage.clear()
  history.replaceState(null, "", "/")
  vi.stubGlobal("fetch", vi.fn(async (input: RequestInfo | URL) => {
    const url = String(input)
    if (url === "/api/v1/sessions") return response({ sessionId: "session-1" }, 201)
    if (url.includes("/snapshot")) return response({ sessionId: "session-1", transcript: [], lastEventSeq: 0 })
    if (url.includes("/events")) return response({ events: [] })
    return response({ runId: "run-1" }, 202)
  }))
})

test("creates a session and keeps composer state local", async () => {
  render(<App />)
  fireEvent.click(screen.getByRole("button", { name: "New session" }))
  const input = await screen.findByRole("textbox", { name: "Message" })
  fireEvent.change(input, { target: { value: "hello" } })
  expect(input).toHaveValue("hello")
  expect(screen.getByRole("button", { name: "Send" })).toBeEnabled()
})

test("renders restored transcript", async () => {
  localStorage.setItem("ji.sessionId", "session-1")
  vi.stubGlobal("fetch", vi.fn(async (input: RequestInfo | URL) => {
    const url = String(input)
    if (url.includes("/snapshot")) return response({
      sessionId: "session-1",
      transcript: [{ id: "message-1", role: "assistant", text: "restored", toolCalls: [] }],
      lastEventSeq: 3,
    })
    return response({ events: [] })
  }))
  render(<App />)
  expect(await screen.findByText("restored")).toBeInTheDocument()
})

function response(body: unknown, status = 200) {
  return Promise.resolve(new Response(JSON.stringify(body), { status, headers: { "Content-Type": "application/json" } }))
}
